def compute(vars):
    total_size = vars["v1"]
    number_of_data_centers = vars["v2"]

    if number_of_data_centers == 0:
        return None

    value = total_size / number_of_data_centers

    return {
        "value": value,
        "trace": {
            "total_size": total_size,
            "number_of_data_centers": number_of_data_centers,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "square feet per data center"
            }
        }
    }
